mapper.select:
SELECT f.id AS friendship_id, u.id AS user_id, u.nickname, u.birth_year, u.gender, u.country, p.intro, p.photo_key, u.last_seen_at, f.accepted_at,
CASE WHEN f.requester_id = #{userId} THEN f.requester_pinned_at ELSE f.addressee_pinned_at END AS pinned_at, (SELECT ur.code FROM user_regions ur WHERE ur.user_id = u.id LIMIT 1) AS region, (SELECT r.id FROM chat_rooms r WHERE r.type = 'FRIEND' AND r.status = 'ACTIVE' AND r.active_pair_key = f.pair_key LIMIT 1) AS room_id FROM friendships f JOIN users u ON u.id = CASE WHEN f.requester_id = #{userId} THEN f.addressee_id ELSE f.requester_id END LEFT JOIN user_profiles p ON p.user_id = u.id WHERE (f.requester_id = #{userId} OR f.addressee_id = #{userId}) AND f.status = 'ACCEPTED' AND u.gender = #{gender} AND u.country = #{country} AND (YEAR(CURDATE()) - u.birth_year) >= #{ageMin} AND (YEAR(CURDATE()) - u.birth_year) <= #{ageMax}
ORDER BY f.accepted_at DESC

mapper.update:
UPDATE friendships SET viewed_at = NOW()
WHERE id = #{id} AND addressee_id = #{userId}
  AND status = 'PENDING' AND viewed_at IS NULL
